<?php
declare(strict_types=1);
require_once __DIR__ . '/config/app.php';
require_once __DIR__ . '/includes/notifications.php';

$user = require_login(); $userId = (int) $user['id']; $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        verify_csrf(); $action = (string) ($_POST['action'] ?? '');
        $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
        if ($action === 'all') { mark_notifications_read($userId); set_flash('success', 'All notifications marked as read.'); }
        elseif ($action === 'read' && $id) { mark_notification_read($userId, $id); set_flash('success', 'Notification marked as read.'); }
        elseif ($action === 'delete' && $id) { delete_notification($userId, $id); set_flash('success', 'Notification deleted.'); }
        else { throw new RuntimeException('Invalid notification action.'); }
        redirect('notifications.php?page=' . max(1, (int) ($_GET['page'] ?? 1)));
    } catch (Throwable $exception) { app_log('Notification Center update failed: ' . $exception->getMessage()); $error = 'The notification could not be updated.'; }
}
$perPage = 20; $total = notification_count($userId); $page = min(max(1, (int) ($_GET['page'] ?? 1)), max(1, (int) ceil($total / $perPage))); $notifications = notifications_for_user($userId, $perPage, ($page - 1) * $perPage);
$pageTitle = 'Notifications | ' . APP_NAME; require_once __DIR__ . '/includes/header.php';
?>
<main class="opportunity-page"><div class="container py-5"><div class="opportunity-hero"><div><span class="eyebrow"><i class="bi bi-bell"></i> Notification Center</span><h1>Notifications</h1><p>Updates about opportunities, referrals, and wallet activity.</p></div><?php if ($notifications): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="all"><button class="btn btn-light border">Mark all as read</button></form><?php endif; ?></div><?php if ($error): ?><div class="alert alert-danger mt-4"><?= e($error) ?></div><?php endif; ?><section class="opportunity-list-card mt-4"><?php if (!$notifications): ?><div class="empty-state"><span><i class="bi bi-bell"></i></span><h3>No notifications yet</h3><p>New updates will appear here.</p></div><?php else: ?><div class="list-group list-group-flush"><?php foreach ($notifications as $notification): ?><article class="list-group-item py-3 <?= (int) $notification['is_read'] === 0 ? 'bg-light border-start border-4 border-primary' : 'text-muted' ?>"><div class="d-flex justify-content-between gap-3"><div class="d-flex gap-2"><span class="notification-dot <?= (int) $notification['is_read'] === 0 ? 'bg-primary' : '' ?> mt-2" aria-hidden="true"></span><div><div class="d-flex align-items-center gap-2 flex-wrap"><h2 class="h6 mb-0"><?= e($notification['title']) ?></h2><span class="badge text-bg-<?= (int) $notification['is_read'] === 0 ? 'primary' : 'secondary' ?>"><?= (int) $notification['is_read'] === 0 ? 'Unread' : 'Read' ?></span></div><p class="mb-1 mt-1"><?= e($notification['message']) ?></p><small class="text-muted"><?= e(str_replace('_', ' ', $notification['type'])) ?> · <?= e(date('d M Y, h:i A', strtotime($notification['created_at']))) ?></small></div></div><div class="text-end text-nowrap"><div class="d-flex gap-1 justify-content-end"><?php if (!(int) $notification['is_read']): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?= (int) $notification['id'] ?>"><button class="btn btn-sm btn-light border" aria-label="Mark notification as read"><i class="bi bi-check2"></i></button></form><?php endif; ?><form method="post" data-confirm="Delete this notification?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int) $notification['id'] ?>"><button class="btn btn-sm btn-outline-danger" aria-label="Delete notification"><i class="bi bi-trash"></i></button></form></div></div></div></article><?php endforeach; ?></div><?php endif; ?></section><?php if ($total > $perPage): ?><nav class="mt-4" aria-label="Notification pages"><ul class="pagination justify-content-end mb-0"><?php for ($itemPage = 1; $itemPage <= (int) ceil($total / $perPage); $itemPage++): ?><li class="page-item <?= $itemPage === $page ? 'active' : '' ?>"><a class="page-link" href="<?= e(url('notifications.php?page=' . $itemPage)) ?>"><?= $itemPage ?></a></li><?php endfor; ?></ul></nav><?php endif; ?></div></main>
<?php require_once __DIR__ . '/includes/footer.php'; ?>
